/* Dataset registration only. No browser writes or backend queries. */
function initIngestion(scene){
 if(!scene.ingestion)return;
 const nav=document.getElementById('workbench-views');
 const panel=document.createElement('section');panel.id='ingestion-view';panel.className='card';panel.hidden=true;nav.after(panel);
 const available=value=>value===undefined||value===null?'NOT_AVAILABLE':String(value);
 const make=(tag,value,cls)=>{const e=document.createElement(tag);if(value!==undefined)e.textContent=String(value);if(cls)e.className=cls;return e;};
 let dataset=scene.ingestion.datasets[0];
 function render(){
  panel.replaceChildren();const toolbar=make('div');toolbar.className='toolbar';
  toolbar.append(make('h2','Datasets / Ingestion · REPLAY'));
  const select=make('select');select.setAttribute('aria-label','Registered dataset');
  for(const d of scene.ingestion.datasets){const o=make('option',d.label);o.value=d.id;select.append(o);}select.value=dataset.id;select.onchange=()=>{dataset=scene.ingestion.datasets.find(d=>d.id===select.value);render();};toolbar.append(select);panel.append(toolbar);
  const content=make('div');content.className='side-section';panel.append(content);
  content.append(make('h2',dataset.label),make('p',dataset.id),make('p',dataset.qualification),make('p',dataset.intent));
  content.append(make('p','Source verification at publication: PASS. Historical evidence REPLAY; this is not a new engineering acceptance. Common object catalogue: DEFERRED.'));
  const qualification=dataset.qualification_data;
  if(qualification?.records?.length){
   content.append(make('h2','Recorded qualification · bound receipt values'));
   for(const record of qualification.records){
    const metric=record.metrics,ref=dataset.evidence.find(e=>e.path===record.evidence.path&&e.sha256===record.evidence.sha256);
    const section=make('section');section.dataset.receiptRole=record.role;
    section.append(make('h2',record.role+' · REPLAY'));
    if(record.role==='local'){
     for(const [layer,row] of Object.entries(metric.layers))section.append(make('p',layer+' · symmetric difference '+available(row.symmetric_difference_area_mm2)+' mm² · '+(layer==='Edge.Cuts'?'recorded profile comparison':'ROI '+JSON.stringify(metric.roi_mm)+' Gerber mm')));
    }else if(record.role==='discrepancy'){
     section.append(make('p','Source-only flashes: '+available(metric.source_only_flash_count)+' · native-only flashes: '+available(metric.native_only_flash_count)+' · symmetric difference '+available(metric.symmetric_difference_area_mm2)+' mm² · ROI '+JSON.stringify(metric.roi_mm)+' Gerber mm. Cause unknown.'));
    }else if(record.role==='drills'){
     for(const [kind,row] of Object.entries(metric))section.append(make('p',kind+' · matched hits '+available(row.drills?.matched)+' / source '+available(row.drills?.total_source)+' / native '+available(row.drills?.total_native)+'; position tolerance '+available(row.drills?.position_tolerance_mm)+' mm; tool tolerance '+available(row.drills?.tool_tolerance_mm)+' mm; matched slots '+available(row.slot_match?.matched)+'; endpoint tolerance '+available(row.slot_match?.endpoint_tolerance_mm)+' mm.'));
     section.append(make('p','Original inch files preserved; historical normalized values retain their recorded warnings and tolerances.'));
    }
    if(ref){const a=make('a','Open bound '+record.role+' receipt');a.href=ref.snapshot;a.target='_blank';a.rel='noopener';section.append(a,make('small',' · SHA-256 '+ref.sha256));}
    const details=make('details');details.append(make('summary','Exact stored receipt values'),make('pre',JSON.stringify(metric,null,2)));section.append(details);content.append(section);
   }
   for(const view of qualification.comparisons){
    content.append(make('h2',view.label+' · shared coordinates'));
    const pair=make('div');pair.className='views';pair.dataset.comparison=view.label;
    for(const [pane,title,paths] of [
     ['source','Source artwork',[[view.source_path,'#c8ab77','geometry']]],
     ['native','Native replot',[[view.native_path,'#c8ab77','geometry']]],
     ['delta','Difference only · pink source-only / green native-only',[[view.source_only_path,'#ff87a8','source-only'],[view.native_only_path,'#49dfba','native-only']]]
    ]){
     const column=make('div');if(pane==='delta')column.style.gridColumn='1 / -1';column.append(make('div',title,'view-title'));
     const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('board');svg.setAttribute('viewBox',view.view_box.join(' '));svg.setAttribute('aria-label',view.label+' '+title);svg.dataset.pane=pane;
     for(const [d,color,role] of paths){const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',d);path.setAttribute('fill',color);path.setAttribute('fill-rule','evenodd');path.dataset.role=role;svg.append(path);}column.append(svg);pair.append(column);
    }
    content.append(pair,make('p',view.basis+' · Source and native panes contain their own geometry only. Difference pane contains only removed/added geometry.'));
    const inputs=make('details');inputs.append(make('summary','Exact rendered source/native hashes'),make('pre',JSON.stringify(view.inputs,null,2)));content.append(inputs);
   }
   content.append(make('p','Native (x,y) → Gerber (x,-y) → display (x,y), millimetres, no best fitting. Client native Processing/Storage ingestion: NOT_IMPLEMENTED. Whole-board equivalence, independent electrical intent and manufacturing: NOT_ESTABLISHED.'));
  }else content.append(make('p','Additional correspondence/drill measurements: NOT_AVAILABLE for this dataset. Consult its scoped bound evidence.'));
  if(dataset.case_id){const button=make('button','Inspect recorded case / controls');button.onclick=()=>{document.querySelector('[data-case="'+dataset.case_id+'"]').click();const cases=[...nav.children].find(b=>b.textContent==='Cases');cases?.click();};content.append(button);}
  content.append(make('h2','Bound evidence'));
  for(const row of dataset.evidence){const p=make('p'),a=make('a',row.path);a.href=row.snapshot;a.target='_blank';a.rel='noopener';p.append(a,make('small',' · SHA-256 '+row.sha256));content.append(p);}
  const details=make('details');details.append(make('summary','Source content revisions and exact hashes ('+dataset.sources.length+')'),make('pre',JSON.stringify(dataset.sources,null,2)));content.append(details);
  content.append(make('p','SQLite ordered access / Rtree candidates / GEOS predicates remain reference paths. DB0 SHADOW_ONLY; historical parity does not qualify this client ingestion. Cursor NOT_RUN: CHANNEL_UNAVAILABLE.'));
 }
 const entry=make('button','Datasets / Ingestion');entry.id='ingestion-tab';entry.onclick=()=>{for(const b of nav.children)b.classList.toggle('active',b===entry);document.getElementById('case-view').hidden=true;document.getElementById('pipeline-view').hidden=true;panel.hidden=false;document.getElementById('headline').textContent='Datasets / Ingestion';document.getElementById('story').textContent='Retained sources, provenance, bounded qualification and evidence';render();};nav.append(entry);
 nav.addEventListener('click',event=>{if(event.target!==entry&&event.target.tagName==='BUTTON')panel.hidden=true;});
}

/* DOM contract regressions for the production ingestion renderer. Run with Node. */
const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const path=require('node:path');
class Element {
 constructor(tag){this.tag=tag;this.children=[];this.dataset={};this.style={};this.attrs={};this.classList={add:()=>{},toggle:()=>{}};this._text='';}
 set textContent(value){this._text=String(value);this.children=[];}
 get textContent(){return this._text+this.children.map(c=>c.textContent||'').join(' ');}
 append(...items){this.children.push(...items);}
 replaceChildren(...items){this.children=items;}
 setAttribute(k,v){this.attrs[k]=v;}
 after(item){this.following=item;}
 addEventListener(){}
}
function descend(node,predicate){return [node,...node.children.flatMap(n=>descend(n,predicate))].filter(predicate);}
function run(){
 const nav=new Element('nav');const nodes={'workbench-views':nav,'case-view':new Element('div'),'pipeline-view':new Element('div'),'headline':new Element('h1'),'story':new Element('p')};
 const document={getElementById:id=>nodes[id],createElement:t=>new Element(t),createElementNS:(_,t)=>new Element(t)};
 const context=vm.createContext({document});vm.runInContext(fs.readFileSync(path.join(__dirname,'../../web/ingestion_views.js'),'utf8'),context);
 const evidence=[{path:'local',sha256:'a',snapshot:'local.json'},{path:'discrepancy',sha256:'b',snapshot:'diff.json'},{path:'drills',sha256:'c',snapshot:'drill.json'}];
 const data={id:'client:first',label:'First',qualification:'Partial',intent:'Unknown',sources:[],evidence,qualification_data:{records:[
  {role:'local',evidence:evidence[0],metrics:{roi_mm:[1,2,3,4],layers:{'B.Cu':{symmetric_difference_area_mm2:1.234}}}},
  {role:'discrepancy',evidence:evidence[1],metrics:{source_only_flash_count:7,native_only_flash_count:2,symmetric_difference_area_mm2:8.765,roi_mm:[1,2,3,4]}},
  {role:'drills',evidence:evidence[2],metrics:{PTH:{drills:{matched:123,total_source:125,total_native:124,position_tolerance_mm:.009,tool_tolerance_mm:.008},slot_match:{matched:3,endpoint_tolerance_mm:.007}}}}
 ],comparisons:[{label:'Known difference',view_box:[0,0,4,4],source_path:'M0 0 L1 0 Z',native_path:'M2 2 L3 2 Z',source_only_path:'M0 0 L.5 0 Z',native_only_path:'',inputs:{},basis:'REPLAY'}]}};
 context.scene={ingestion:{datasets:[data,{id:'client:second',label:'Second',sources:[],evidence:[],qualification:'Unknown',intent:'Unknown',qualification_data:{records:[],comparisons:[]}}]}};
 vm.runInContext('initIngestion(scene)',context);nav.children.find(e=>e.id==='ingestion-tab').onclick();const panel=nav.following;
 const panes=descend(panel,n=>n.tag==='svg');const native=panes.find(p=>p.dataset.pane==='native'),source=panes.find(p=>p.dataset.pane==='source'),delta=panes.find(p=>p.dataset.pane==='delta');
 assert.equal(native.children.length,1);assert.equal(native.children[0].attrs.d,data.qualification_data.comparisons[0].native_path);assert.equal(source.children.length,1);assert.equal(source.children[0].attrs.d,data.qualification_data.comparisons[0].source_path);assert.equal(delta.children.length,2);assert.equal(delta.children[0].attrs.d,data.qualification_data.comparisons[0].source_only_path);
 assert.match(panel.textContent,/Source-only flashes: 7/);assert.match(panel.textContent,/1\.234 mm²/);assert.match(panel.textContent,/matched hits 123/);assert.match(panel.textContent,/position tolerance 0\.009 mm/);
 data.qualification_data.records[1].metrics.source_only_flash_count=9;data.qualification_data.records[2].metrics.PTH.drills.matched=321;
 let select=descend(panel,n=>n.tag==='select')[0];select.value=data.id;select.onchange();assert.match(panel.textContent,/Source-only flashes: 9/);assert.match(panel.textContent,/matched hits 321/);
 select=descend(panel,n=>n.tag==='select')[0];select.value='client:second';select.onchange();assert.match(panel.textContent,/NOT_AVAILABLE/);assert.doesNotMatch(panel.textContent,/Source-only flashes:|matched hits|R140\.1|4,894/);
 return {status:'PASS',checks:['Pure source/native panes; differences confined to delta','Receipt-driven changed comparison/drill values; no cross-dataset leakage']};
}
module.exports={run};
if(require.main===module)console.log(JSON.stringify(run()));

